import sequelize from "../config/dbConfig.js";
import { QueryTypes } from "sequelize";
import jwt from "jsonwebtoken";
import { authenticate } from "../middlewares/ldapService.js";
import config from "../config/envConfig.js";
import { hashPassword, verifyPassword } from "../util/hashUtil.js";
import { getAllLdapGroupsWithDESC, syncGroupsAndMembers } from "../util/ldap/ldapUtils.js";
import { ok, fail, serverError } from "../util/response.js";

export const generateTokens = (user) => {
  //const { ACCESS_TOKEN_SECRET, ACCESS_TOKEN_EXPIRES_IN, REFRESH_TOKEN_SECRET, REFRESH_TOKEN_EXPIRES_IN } = config;
  const ACCESS_TOKEN_SECRET = config.ACCESS_TOKEN_SECRET;
  const REFRESH_TOKEN_SECRET = config.REFRESH_TOKEN_SECRET;

  const accessToken = jwt.sign(
    {
      userId: user.user_id,
      groupId: user.group_id,
      language: user.prefered_language,
    },
    ACCESS_TOKEN_SECRET,
    { expiresIn: "15m" } // Short-lived access token
  );

  const refreshToken = jwt.sign(
    {
      userId: user.user_id,
      groupId: user.group_id,
      language: user.prefered_language,
    },
    REFRESH_TOKEN_SECRET,
    { expiresIn: "8h" } // Long-lived refresh token
  );

  return { accessToken, refreshToken };
};

// Helper function to set HTTP-only cookie
function setRefreshTokenCookie(res, refreshToken) {
  res.cookie("refreshToken", refreshToken, {
    httpOnly: true,
    sameSite: "strict",
    //secure: process.env.NODE_ENV === "production",
    //sameSite: process.env.NODE_ENV === "production" ? "none" : "lax",
    maxAge: 12 * 60 * 60 * 1000, // 12h
    //path: "/",
    // domain: process.env.COOKIE_DOMAIN || undefined,
  });
}

export const protectedRoute = (req, res) => {
  return ok(res, { user: req.user }, "This is a protected route");
};

export const refreshToken = async (req, res) => {
  const REFRESH_TOKEN_SECRET = config.REFRESH_TOKEN_SECRET;
  const refreshToken = req.cookies.refreshToken;
  if (!refreshToken) return fail(res, "Unauthorized", 401);

  try {
    const decoded = jwt.verify(refreshToken, REFRESH_TOKEN_SECRET);
    // Check if user exists
    const users = await sequelize.query(`SELECT * FROM "user" WHERE user_id = $1 AND active = 'Y' AND locked = 'N'`, {
      bind: [decoded.userId],
      type: QueryTypes.SELECT,
    });
    if (users.length === 0) {
      return fail(res, "User not found", 401);
    }
    const user = users[0];
    const shouldRefreshRefreshToken = decoded.exp * 1000 - Date.now() < 60 * 60 * 1000; // 1h remaining

    const { accessToken, refreshToken: newRefreshToken } = generateTokens(user);
    if (shouldRefreshRefreshToken) {
      res.cookie("refreshToken", newRefreshToken, {
        httpOnly: true,
        sameSite: "strict",
        maxAge: 12 * 60 * 60 * 1000, // 12 h
      });
    }
    return ok(res, {
      accessToken,
      user: {
        userId: user.user_id,
        groupId: user.group_id,
        language: user.prefered_language || "en",
      },
    }, "Token refreshed");
  } catch (error) {
    console.error("from refresh token " + error);
    return fail(res, "Forbidden", 403);
  }
};

export const changeUserLanguage = async (req, res) => {
  console.log("from change lang");
  const { userId } = req.user; // Assuming userId is extracted from the JWT
  const { language } = req.query;
  console.log(language);
  if (!language) {
    return fail(res, "Language is required", 400);
  }

  try {
    // 1. Update the user's preferred language in the database
    const updatedRows = await sequelize.query(
      `UPDATE "user" SET prefered_language = $1 WHERE user_id = $2 RETURNING *`,
      { bind: [language, userId], type: QueryTypes.SELECT }
    );

    if (updatedRows.length === 0) {
      return fail(res, "User not found", 404);
    }

    const updatedUser = updatedRows[0];

    // 2. Generate new tokens with updated language preference
    const { accessToken, refreshToken } = generateTokens(updatedUser);
    setRefreshTokenCookie(res, refreshToken);

    // 3. Return success response with new tokens
    return ok(res, {
      accessToken,
      user: {
        userId: updatedUser.user_id,
        groupId: updatedUser.group_id,
        language: updatedUser.prefered_language,
      },
    }, "Language updated successfully");
  } catch (error) {
    console.error("Error updating language:", error);
    return serverError(res, "Server error while updating language", error);
  }
};

// update login code with LDAP PRIORITY
export const loginUser = async (req, res) => {
  const { userName, password } = req.body;
  console.log(`Login attempt for user: ${userName}`);
  // return res.json({msg :"success"})

  try {
    const authPriority = config.AUTH_PERIORITY || "local"; // Default to 'local' if not set

    // 1. Check authentication priority and proceed accordingly
    if (authPriority.toLowerCase() === "ldap") {
      // LDAP first authentication flow
      try {
        // Attempt LDAP authentication first
        const { status, message } = await authenticate(userName, password);
        //console.log(message);
        // LDAP succeeded, now check local user
        const users = await sequelize.query(`SELECT * FROM "user" WHERE user_name = $1`, { bind: [userName], type: QueryTypes.SELECT });
        let user = users[0];

        if (!user) {
          // User doesn't exist locally - create new user
          try {
            await sequelize.query(
              `INSERT INTO "user" 
                         (user_name, password, active, locked, prefered_language, creation_date)
                         VALUES ($1, $2,'N', 'Y', 'en', NOW())
                         RETURNING *`,
              { bind: [userName, await hashPassword(password)], type: QueryTypes.SELECT }
            );
            return fail(res, "LDAP authentication succeeded, new local account created. Please contact administrator to assign group .", 403);
          } catch (createError) {
            console.error("Failed to create local user:", createError);
            return serverError(res, "LDAP authentication succeeded but failed to create local account. Please contact administrator.", createError);
          }
        }

        // Check if local user is active/locked
        if (user.active !== "Y" || user.locked !== "N") {
          return fail(res, "Your account is locked or inactive. Contact support.", 403);
        }

        // Proceed with successful login
        return await handleSuccessfulLogin(user, res);
      } catch (ldapError) {
        // LDAP failed, fall back to local authentication
        console.log("LDAP authentication failed, falling back to local authentication");
        return await attemptLocalLogin(userName, password, res);
      }
    } else {
      // Local first authentication flow (original flow)
      return await attemptLocalLogin(userName, password, res);
    }
  } catch (error) {
    console.error(error);
    return serverError(res, "Server error", error);
  }
};

// Helper function for local authentication
async function attemptLocalLogin(userName, password, res) {
  // 1. Check if user exists in the local database
  const users = await sequelize.query(`SELECT * FROM "user" WHERE user_name = $1`, { bind: [userName], type: QueryTypes.SELECT });
  const user = users[0];

  // 2. If user exists locally but is locked/inactive, block login
  if (user) {
    if (user.active !== "Y" || user.locked !== "N") {
      return fail(res, "Your account is locked or inactive. Contact support.", 403);
    }

    // 3. Validate local password
    const isMatch = await verifyPassword(password, user.password);
    if (isMatch) {
      return await handleSuccessfulLogin(user, res);
    }
  }

  // 4. If user doesn't exist locally or password fails, try LDAP
  try {
    const { status, message } = await authenticate(userName, password);

    // 5. LDAP succeeded, but user has no local account → create new local account and BLOCK
    // User doesn't exist locally - create new user

    await sequelize.query(
      `INSERT INTO "user" 
                   (user_name, password, active, locked, prefered_language, creation_date)
                   VALUES ($1, $2,'N', 'Y', 'en', NOW())
                   RETURNING *`,
      { bind: [userName, await hashPassword(password)], type: QueryTypes.SELECT }
    );
    return fail(res, "LDAP authentication succeeded, new local account created. Please contact administrator to assign group .", 403);
  } catch (ldapError) {
    // 6. LDAP failed → Generic error
    return fail(res, "Incorrect username or password", 401);
  }
}

// Helper function for successful login flow
async function handleSuccessfulLogin(user, res) {
  // 1. Check if the user's group has assigned menus
  const menus = await sequelize.query(
    `SELECT ug.group_id, am.menu_id, am.description
     FROM user_group ug
     INNER JOIN app_menu am ON ug.menu_id = am.menu_id
     WHERE ug.group_id = $1`,
    { bind: [user.group_id], type: QueryTypes.SELECT }
  );

  if (menus.length === 0) {
    return fail(res, "No menu has been assigned to your group. Contact your administrator.", 403);
  }

  // 2. Generate tokens and proceed with login
  const { accessToken, refreshToken } = generateTokens(user);
  setRefreshTokenCookie(res, refreshToken);

  delete user.password;
  return ok(res, {
    accessToken,
    user: {
      userId: user.user_id,
      groupId: user.group_id,
      language: user.prefered_language || "en",
    },
  }, "Login successful");
}
// fetch all groups with description from ldap

export const listLdapGroupsWithDesc = async (req, res) => {
  getAllLdapGroupsWithDESC((err, groups) => {
    if (err) {
      console.error("Error in listLdapGroupsWithDesc:", err);
      return serverError(res, "Failed to fetch LDAP groups", err);
    }
    return ok(res, { groups }, "Success");
  });
};

// Controller to import groups and users from LDAP
export const syncGroupsAndMembersLdap = async (req, res) => {
  try {
    const { groups } = req.body; // destructuring directly
    console.log("from ldap save group");
    if (!Array.isArray(groups)) {
      return fail(res, "Invalid request format: 'groups' must be an array.", 400);
    }

    if (groups.length === 0) {
      return fail(res, "No groups provided to sync.", 400);
    }

    await syncGroupsAndMembers(groups);

    return ok(res, {}, "Groups and members synced successfully!");
  } catch (error) {
    console.error("Error in syncGroupsAndMembers:", error);
    return serverError(res, "Failed to sync groups and members", error);
  }
};
